out=[]
for key,term,match,cs,vi,ref in T:
    d={"key":key,"term":term,"vi":vi}
    if match: d["match"]=match
    if cs: d["cs"]=True
    if ref: d["ref"]=ref
    out.append(d)
assert len({x["key"] for x in out})==len(out)
json.dump(out,open(os.path.join(os.path.dirname(__file__),"terms.json"),"w"),ensure_ascii=False,indent=1)
print(len(out))
